package com.nextrade.engine.matching; import com.nextrade.common.enumtype.*; import com.nextrade.common.identifier.*; import java.util.*; public record MatchingResult(OrderId orderId,OrderStatus finalStatus,List<TradeExecution> trades,String rejectionReason){public boolean accepted(){return rejectionReason==null;}public boolean filled(){return finalStatus==OrderStatus.FILLED;}public static MatchingResult rejected(OrderId id,String reason){return new MatchingResult(id,OrderStatus.REJECTED,List.of(),reason);}}
